// find the visible carrier of the economy allowance text and bring it on screen
const probe = phi.js(() => {
  const out = [];
  const all = Array.from(document.querySelectorAll("*"));
  for (const el of all) {
    if (el.children.length === 0 && /44lb|50lb/.test(el.textContent || "")) {
      const r = el.getBoundingClientRect();
      const cs = getComputedStyle(el);
      out.push({
        tag: el.tagName,
        text: el.textContent.replace(/\s+/g, " ").trim().slice(0, 60),
        w: Math.round(r.width), h: Math.round(r.height),
        disp: cs.display, vis: cs.visibility,
        inHiddenAncestor: el.offsetParent === null
      });
    }
  }
  return out.slice(0, 12);
});
let scrolledTo = null;
const did = phi.js(() => {
  const cands = Array.from(document.querySelectorAll("td,div,span,li,p"))
    .filter(el => el.offsetParent !== null && el.getBoundingClientRect().height > 0 && /20kg \(44lb\)/.test(el.textContent || "") );
  if (!cands.length) return { ok: false };
  cands[cands.length - 1].scrollIntoView({ block: "center" });
  const r = cands[cands.length - 1].getBoundingClientRect();
  return { ok: true, top: Math.round(r.top), h: Math.round(r.height), scrollY: Math.round(window.scrollY) };
});
phi.sleep(1200);
return { probe, did };

const tables = phi.js(() => {
  const out = [];
  Array.from(document.querySelectorAll("table")).forEach((t, i) => {
    const r = t.getBoundingClientRect();
    const cs = getComputedStyle(t);
    let anc = t, hiddenAnc = null;
    while (anc && anc !== document.body) {
      const a = getComputedStyle(anc);
      if (a.display === "none" || a.visibility === "hidden" || anc.getAttribute("aria-hidden") === "true") { hiddenAnc = anc.tagName + "." + (anc.className || "").toString().slice(0,50); break; }
      anc = anc.parentElement;
    }
    out.push({ i, w: Math.round(r.width), h: Math.round(r.height), top: Math.round(r.top), disp: cs.display, hiddenAnc, txt: t.innerText.replace(/\s+/g," ").slice(0,80) });
  });
  return out;
});
phi.narrate("checking which copy of the allowance table is the visible one");
return tables;

