const info = phi.js(() => {
  const t = Array.from(document.querySelectorAll("table"))[1];
  if (!t) return { err: "no table 1" };
  const rows = Array.from(t.querySelectorAll("tr")).map(tr =>
    Array.from(tr.children).map(td => (td.innerText || "").replace(/\s+/g, " ").trim())
  );
  // find nearest preceding heading / label
  let ctx = [];
  let el = t;
  for (let i = 0; i < 8 && el; i++) { el = el.parentElement; if (el) ctx.push((el.tagName + ": " + (el.innerText || "").replace(/\s+/g, " ").slice(0, 160))); }
  return { rows, ctx };
});
return info;

